"import 'package:flutter/material.dart';
import 'package:project/services/language/language_service.dart';

class LanguageProvider extends ChangeNotifier {
  final LanguageService _languageService;
  late Locale _currentLocale;

  LanguageProvider(this._languageService) {
    _currentLocale = _languageService.initialize();
  }

  Locale get locale => _currentLocale;

  /// Whether the app is synced with the device language
  bool get isUsingDeviceLanguage => _languageService.isUsingDeviceLanguage();

  /// Change the language manually
  Future<void> updateLanguage(Locale newLocale) async {
    if (_currentLocale == newLocale && !isUsingDeviceLanguage) return;

    await _languageService.changeLanguage(newLocale);
    _currentLocale = newLocale;
    notifyListeners();
  }

  /// Toggle the use device language setting
  Future<void> toggleDeviceLanguage(bool useDeviceLanguage) async {
    await _languageService.setUseDeviceLanguage(useDeviceLanguage);
    _currentLocale = _languageService.getCurrentLocale();
    notifyListeners();
  }

  /// A helper to get the native name of the language
  String getNativeLanguageName(String languageCode) {
    switch (languageCode) {
      case 'en':
        return 'English';
      case 'hi':
        return 'हिन्दी';
      case 'kn':
        return 'ಕನ್ನಡ';
      default:
        return 'English';
    }
  }
}
