"import 'package:flutter/material.dart';
import 'package:flutter_gen/gen_l10n/app_localizations.dart';

class LocalizationHelper {
  LocalizationHelper._();

  /// Translates common backend statuses safely.
  /// If the status is unknown, returns the original string or a generic fallback.
  static String status(BuildContext context, String? status) {
    if (status == null) return '-';

    final l10n = AppLocalizations.of(context)!;
    final normalized = status.trim().toLowerCase();

    switch (normalized) {
      case 'pending':
      case 'requested':
        // return l10n.statusPending; // Uncomment once added to ARB
        return 'Pending';
      case 'approved':
      case 'accepted':
        // return l10n.statusApproved;
        return 'Approved';
      case 'rejected':
      case 'declined':
        // return l10n.statusRejected;
        return 'Rejected';
      case 'cancelled':
        // return l10n.statusCancelled;
        return 'Cancelled';
      default:
        // Fallback to capitalizing the first letter of the unknown status
        return status;
    }
  }

  /// Translates gender values from the backend.
  static String gender(BuildContext context, String? gender) {
    if (gender == null) return '-';

    // final l10n = AppLocalizations.of(context)!;
    final normalized = gender.trim().toLowerCase();

    switch (normalized) {
      case 'male':
      case 'm':
        // return l10n.labelMale;
        return 'Male';
      case 'female':
      case 'f':
        // return l10n.labelFemale;
        return 'Female';
      case 'other':
      case 'others':
        // return l10n.labelOther;
        return 'Other';
      default:
        return gender;
    }
  }
}
