class DailyQuoteService {
  DailyQuoteService._();

  static DailyQuote getTodayQuote() {
    final now = DateTime.now();
    // Deterministically select based on the current day of the year
    final dayOfYear = int.parse(now.difference(DateTime(now.year, 1, 1)).inDays.toString());
    final index = dayOfYear % dailyQuotes.length;
    return dailyQuotes[index];
