"import 'package:flutter/material.dart';

class AppBackground extends StatelessWidget {
  final Widget child;

  const AppBackground({super.key, required this.child});

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    // We use the exact palette background colors for the overlay gradient
    final Color topColor = isDark ? const Color(0xFF0B1220) : const Color(0xFFF8FAFC);

    // For the bottom, we use a darker tint to make the buildings pop more in light mode
    final Color bottomColorDark = const Color(0xFF0B1220).withValues(alpha: 0.40);
    final Color bottomColorLight = const Color(0xFFF8FAFC).withValues(alpha: 0.20); 

    return Stack(
      fit: StackFit.expand,
      children: [
        // 1. Background image (fixed full-screen)
        Image.asset(
          'assets/images/login_background.png',
          fit: BoxFit.cover,
          alignment: Alignment.bottomCenter, // Ensure skyline anchors to bottom
        ),

        // 2. Adaptive color overlay
        Container(
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                topColor, // Solid at top so logos and text are perfectly clear
                topColor.withValues(alpha: 0.90),
                isDark ? bottomColorDark : bottomColorLight, // Transparent at bottom to show skyline
              ],
              stops: const [0.0, 0.4, 1.0], // Fade starts halfway down
            ),
          ),
        ),

        // 3. Screen content on top
        child,
      ],
    );
  }
}
"

